// src/screens/HomeScreen.js - главный экран приложения
import React, { useState } from 'react';
import { 
  View, 
  Text, 
  TouchableOpacity, 
  StyleSheet, 
  ScrollView,
  ActivityIndicator,
  Alert 
} from 'react-native';
// useStorage для счетчика удален, чтобы убрать его логику
import useApi from '../hooks/useApi';
import { apiService } from '../services/apiService';
import { Ionicons } from '@expo/vector-icons';

const HomeScreen = ({ navigation }) => {
  // Логика счетчика полностью удалена.

  // Логика API-данных (остается)
  const { data: users, loading: apiLoading, error: apiError, refetch } = useApi(
    'https://jsonplaceholder.typicode.com/users'
  );

  // Логика локальных данных (остается)
  const [localData, setLocalData] = useState([]);
  const [postLoading, setPostLoading] = useState(false);

  const addLocalItem = () => {
    const newItem = {
      id: Date.now(),
      title: `Элемент ${localData.length + 1}`,
      timestamp: new Date().toLocaleTimeString()
    };
    setLocalData(prev => [newItem, ...prev]);
  };

  const createPost = async () => {
    setPostLoading(true);
    try {
      const newPost = {
        title: 'Новый пост',
        body: 'Это тестовый пост',
        userId: 1
      };

      // Имитация задержки и отправка POST-запроса
      await new Promise(resolve => setTimeout(resolve, 1000));
      const result = await apiService.createPost(newPost);

      Alert.alert('Успех', `Пост создан! ID: ${result.id}`);
    } catch (e) {
      Alert.alert('Ошибка', `Не удалось создать пост: ${e.message}`);
    } finally {
      setPostLoading(false);
    }
  };

  const renderUser = (user) => (
    <View key={user.id} style={styles.apiItem}>
      <Text style={styles.apiName}>{user.name}</Text>
      <Text style={styles.apiEmail}>{user.email}</Text>
    </View>
  );

  const renderLocalItem = (item) => (
    <View key={item.id} style={styles.apiItem}>
      <Text style={styles.apiName}>{item.title}</Text>
      <Text style={styles.apiEmail}>Создан: {item.timestamp}</Text>
    </View>
  );

  const NavigationButton = ({ title, screenName, iconName, color }) => (
    <TouchableOpacity 
      style={[styles.navButton, { backgroundColor: color || '#007AFF' }]} 
      onPress={() => navigation.navigate(screenName)}
    >
      <Ionicons name={iconName} size={24} color="white" />
      <Text style={styles.navButtonText}>{title}</Text>
    </TouchableOpacity>
  );

  return (
    <ScrollView style={styles.container}>

      {/* Секция API-данных */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Внешние API-Данные (JSONPlaceholder)</Text>

        <TouchableOpacity 
          style={[styles.button, styles.apiButton]} 
          onPress={refetch}
          disabled={apiLoading}
        >
          <Text style={styles.navButtonText}>
            {apiLoading ? 'Обновление...' : 'Обновить API-данные (GET)'}
          </Text>
        </TouchableOpacity>

        <TouchableOpacity 
          style={[styles.button, styles.postButton]} 
          onPress={createPost}
          disabled={postLoading}
        >
          <Text style={styles.navButtonText}>
            {postLoading ? 'Отправка...' : 'Отправить POST-запрос'}
          </Text>
        </TouchableOpacity>

        {apiError && <Text style={styles.errorText}>Ошибка: {apiError}</Text>}

        {(users && users.length > 0) && (
          <View style={styles.apiList}>
            <Text style={styles.listHeader}>Список пользователей:</Text>
            {users.slice(0, 3).map(renderUser)}
          </View>
        )}
      </View>

      {/* Секция Локальные данные */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Локальные данные в памяти</Text>
        <TouchableOpacity 
          style={[styles.button, styles.localButton]} 
          onPress={addLocalItem}
        >
          <Text style={styles.navButtonText}>Добавить локальный элемент</Text>
        </TouchableOpacity>

        {(localData.length > 0) && (
          <View style={styles.apiList}>
            <Text style={styles.listHeader}>Последние элементы:</Text>
            {localData.slice(0, 3).map(renderLocalItem)}
          </View>
        )}
      </View>

      {/* Секция Навигация */}
      <View style={[styles.section, { padding: 5, paddingVertical: 10 }]}>
        <Text style={styles.sectionTitle}>Навигация</Text>
        <View style={styles.navRow}>
          <NavigationButton title="Мультимедиа" screenName="Media" iconName="videocam-outline" color="#34C759" />
          <NavigationButton title="Галерея" screenName="Gallery" iconName="images-outline" color="#FF9500" />
        </View>
        <View style={styles.navRow}>
          <NavigationButton title="Аналитика" screenName="Analytics" iconName="analytics-outline" color="#5856D6" />
          <NavigationButton title="Настройки" screenName="Settings" iconName="settings-outline" color="#FF3B30" />
        </View>
      </View>
    </ScrollView>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#f5f5f5',
  },
  section: {
    backgroundColor: 'white',
    margin: 10,
    borderRadius: 10,
    padding: 15,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.1,
    shadowRadius: 4,
    elevation: 3,
  },
  sectionTitle: {
    fontSize: 20,
    fontWeight: 'bold',
    marginBottom: 10,
    color: '#333',
  },
  navRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    marginBottom: 10,
  },
  navButton: {
    paddingHorizontal: 15,
    paddingVertical: 12,
    borderRadius: 8,
    alignItems: 'center',
    justifyContent: 'center',
    flex: 1,
    marginHorizontal: 5,
    flexDirection: 'row',
    gap: 8,
  },
  navButtonText: {
    color: 'white',
    fontSize: 16,
    fontWeight: '600',
    textAlign: 'center',
  },
  button: {
    paddingHorizontal: 20,
    paddingVertical: 12,
    borderRadius: 8,
    alignItems: 'center',
    marginVertical: 5,
    backgroundColor: '#007AFF',
  },
  apiButton: {
    backgroundColor: '#34C759',
    marginBottom: 10,
  },
  postButton: {
    backgroundColor: '#FF9500',
    marginBottom: 10,
  },
  localButton: {
    backgroundColor: '#007AFF',
  },
  errorText: {
    color: '#FF3B30',
    marginTop: 10,
    textAlign: 'center',
  },
  apiList: {
    marginTop: 10,
    borderTopWidth: 1,
    borderTopColor: '#eee',
    paddingTop: 10,
  },
  listHeader: {
    fontWeight: '600',
    marginBottom: 5,
    color: '#333',
  },
  apiItem: {
    backgroundColor: '#f8f8f8',
    padding: 10,
    borderRadius: 5,
    marginBottom: 5,
  },
  apiName: {
    fontWeight: 'bold',
  },
  apiEmail: {
    fontSize: 12,
    color: '#666',
  },
});

export default HomeScreen;
